<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {Search,Download,LoaderCircle} from 'lucide-vue-next'
import {api,query,downloadFile} from './api'
import {useFeedback} from './feedback'
type Item=Record<string,any>
const props=defineProps<{meta:Item}>()
const kind=ref('habit'),target=ref('student'),search=ref(''),year=ref(''),term=ref(''),period=ref(''),course=ref(''),time=ref(''),page=ref(1),result=ref<Item>({items:[],total:0,fields:[],averages:{}}),busy=ref(false)
const {error}=useFeedback()
const spec=computed(()=>props.meta.kinds[kind.value]),maxPage=computed(()=>Math.max(1,Math.ceil(result.value.total/30)))
function params(){return {kind:kind.value,target:target.value,search:search.value,year:year.value,term:term.value,period:period.value,class_type:course.value,class_time:time.value}}
function val(v:any,type=''){return v===null||v===undefined||v===''?'—':type==='percent'?v+'%':v}
let version=0
async function load(){const v=++version;busy.value=true;error.value='';try{const data=await api(`teaching/rows/?${query({...params(),offset:(page.value-1)*30})}`);if(v===version)result.value=data}catch(e){if(v===version)error.value=(e as Error).message}finally{if(v===version)busy.value=false}}
watch(kind,()=>{period.value='';course.value='';time.value='';page.value=1;load()})
watch([target,year,term,period,course,time],()=>{page.value=1;load()});watch(page,load)
async function download(){busy.value=true;error.value='';try{await downloadFile(`teaching/export/?${query({...params(),mode:'detail'})}`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel workflow-panel"><form class="workflow-toolbar" @submit.prevent="page=1;load()"><label>搜索内容<select v-model="kind"><option v-for="(s,id) in meta.kinds" :key="id" :value="id">{{s.name.replace('数据上传','').replace('上传','')}}</option></select></label><label>搜索对象<select v-model="target"><option value="student">学生</option><option value="teacher">教师</option></select></label><label class="field search-grow">姓名<input v-model="search" :placeholder="target==='teacher'?'教师姓名或 *':'中文名、英文名或 *'"/></label><button class="btn primary" :disabled="busy"><Search :size="16"/>搜索</button></form><div class="workflow-toolbar"><label>年份<input v-model="year" placeholder="全部年份" inputmode="numeric"/></label><label>学期<select v-model="term"><option value="">全部学期</option><option>春</option><option>夏</option><option>秋</option><option>全年</option></select></label><label>期次<select v-model="period"><option value="">全部期次</option><option v-for="n in spec.periods" :key="n" :value="String(n)">{{kind==='scores'?(n===1?'期中':'期末'):`第 ${n} ${spec.unit}`}}</option></select></label><label>课型<select v-model="course"><option value="">全部课型</option><option v-for="c in result.courses" :key="c">{{c}}</option></select></label><label>时间段<select v-model="time"><option value="">全部时间段</option><option v-for="t in result.times" :key="t">{{t}}</option></select></label><span class="toolbar-spacer"></span><button class="btn" :disabled="busy||!result.total" @click="download"><Download :size="16"/>导出筛选结果</button></div><div v-if="busy" class="loading-inline"><LoaderCircle class="spin" :size="17"/>正在查询…</div><div class="table-scroll"><table><thead><tr><th>年份／学期</th><th>期次</th><th>教师</th><th>学生</th><th>英文名</th><th>课型／时间段</th><th v-for="f in spec.fields" :key="f[0]">{{f[1]}}</th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><td>{{r.year}} / {{r.term}}</td><td>{{r.period}}</td><td>{{r.teacher}}</td><td>{{r.student_name}}</td><td>{{r.english_name||'—'}}</td><td>{{r.class_type}} / {{r.class_time}}</td><td v-for="f in spec.fields" :key="f[0]" :class="{'wrap-cell':f[0]==='content'}">{{val(r.data[f[0]],f[2])}}</td></tr><tr v-if="result.total" class="average-row"><td colspan="6">平均值（星币合计）</td><td v-for="f in spec.fields" :key="f[0]">{{val(result.averages?.[f[0]],f[2])}}</td></tr></tbody></table><div v-if="!result.total&&!busy" class="empty-state compact">暂无符合条件的已上传数据。</div></div><div class="workflow-footer"><span>共 {{result.total}} 条</span><div class="pagination"><button class="btn small" :disabled="page<=1||busy" @click="page--">上一页</button><span>{{page}} / {{maxPage}}</span><button class="btn small" :disabled="page>=maxPage||busy" @click="page++">下一页</button></div></div></section></template>
